    <section class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><label class="text-sm">From<input wire:model.live="dateFrom" type="date" class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2"></label><label class="text-sm">To<input wire:model.live="dateTo" type="date" class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2"></label><label class="text-sm">Division<select wire:model.live="divisionId" class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2"><option value="">All accessible divisions</option>@foreach($this->divisions as $division)<option value="{{ $division->id }}">{{ $division->name }}</option>@endforeach</select></label><label class="text-sm">Type<select wire:model.live="documentType" class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2"><option value="">All types</option><option value="custom">Custom type</option>@foreach($this->documentTypes as $type)<option value="{{ $type->id }}">{{ $type->name }}</option>@endforeach</select></label><label class="text-sm">Status<select wire:model.live="status" class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2"><option value="">All statuses</option>@foreach(DocumentReportQuery::STATUSES as $value)<option value="{{ $value }}">{{ str($value)->replace('_', ' ')->title() }}</option>@endforeach</select></label></div></section>
