    <div class="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">@foreach(['Total submitted' => $this->summary['total_submitted'], 'Pending acknowledgment' => $this->summary['pending_acknowledgment'], 'In progress' => $this->summary['in_progress'], 'Completed' => $this->summary['completed'], 'Cancelled' => $this->summary['cancelled'], 'Revision requested' => $this->summary['revision_requested'], 'Average processing time' => $this->duration($this->summary['average_processing_seconds'])] as $label => $value)<article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><p class="text-sm text-slate-500">{{ $label }}</p><p class="mt-2 text-2xl font-bold">{{ $value }}</p></article>@endforeach</div>
