    <section class="mt-6 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="border-b border-slate-200 px-5 py-4"><h2 class="font-semibold">Division activity</h2><p class="mt-1 text-sm text-slate-500">Counts are distinct documents. Forwarded counts include normal forward-route events only.</p></div><div class="overflow-x-auto"><table class="min-w-full text-sm"><thead class="bg-slate-50 text-left text-xs uppercase text-slate-500"><tr><th class="px-5 py-3">Division</th><th class="px-3 py-3">Originated</th><th class="px-3 py-3">Received</th><th class="px-3 py-3">Forwarded</th><th class="px-3 py-3">Completed</th><th class="px-3 py-3">Assigned</th></tr></thead><tbody class="divide-y divide-slate-100">@forelse($this->divisionMetrics as $metric)<tr><td class="px-5 py-3 font-medium">{{ $metric->name }}</td><td class="px-3 py-3">{{ $metric->originated }}</td><td class="px-3 py-3">{{ $metric->received }}</td><td class="px-3 py-3">{{ $metric->forwarded }}</td><td class="px-3 py-3">{{ $metric->completed }}</td><td class="px-3 py-3">{{ $metric->assigned }}</td></tr>@empty<tr><td colspan="6" class="px-5 py-8 text-center text-slate-500">No division activity matches these filters.</td></tr>@endforelse</tbody></table></div></section>
